32	    protected static function booted(): void
33	    {
34	        // strategia orfani (opzione C, design §3.6): al salvataggio rimuove dal JSON
35	        // degli attributi le chiavi non più previste dallo schema corrente (risolto
36	        // dalla tipologia già assegnata sul record). L'utente è avvisato a monte
37	        // dall'alert inline nel ProductForm; qui avviene lo strip effettivo.
38	        static::saving(function (self $product): void {
39	            // se la tipologia è cambiata, la relazione productType potrebbe essere
40	            // ancora quella vecchia in cache: la scarico così lo schema viene
41	            // risolto dalla tipologia appena assegnata.
42	            if ($product->isDirty('product_type_id')) {
43	                $product->unsetRelation('productType');
44	            }
45	
46	            $product->setAttribute(
47	                $product->attributesColumn(),
48	                $product->stripOrphanAttributes($product->attributeSchema()),
49	            );
50	        });
51	    }
52	
53	    /**
54	     * Lo schema attributi del Product è determinato dalla ProductType associata.
55	     * Se la ProductType non ha uno schema configurato, il prodotto non ha attributi tipizzati.
56	     */
57	    public function resolveAttributeSchemaClass(): ?string
58	    {
59	        $class = $this->productType?->attribute_schema_class;
60	
61	        return is_string($class) && is_subclass_of($class, AttributeSchema::class) ? $class : null;
62	    }
63	
64	
65	    /**
66	     * Nome comprensivo del nome collezione (category2)
67	     */
68	    public function catalogName(?string $locale = null): string
69	    {
70	        $locale ??= app()->getLocale();
71	        // @phpstan-ignore binaryOp.invalid,binaryOp.invalid
72	        return $this->category2?->getTranslation('name', $locale)
73	            . ' ' . $this->getTranslation('name', $locale);
74	    }
75	
76	    /**
77	     * Padre nella composizione (il "divano modulare" wrapper). Null per i
78	     * prodotti non componibili e per gli stessi wrapper.
79	     *
80	     * @return BelongsTo<Product, $this>
81	     */
82	    public function parent(): BelongsTo
83	    {
84	        return $this->belongsTo(self::class, 'parent_id');
85	    }
86	
