use App\Models\{Product, Material};
$counts = Material::query()->get()->groupBy(fn($m)=>$m->material_category_id ?? "")->map->count();
echo "gruppi materiali per categoria: ".$counts->toJson()."\n";

$p = Product::query()->first();
if(!$p){ echo "no product\n"; return; }
echo "prodotto: ".$p->id."\n";
$before = $p->materials()->pluck("materials.id")->all();
echo "materiali prima: ".json_encode($before)."\n";

// simula il save di una categoria: prendo la prima categoria non vuota
$cat = Material::query()->whereNotNull("material_category_id")->first();
$catId = $cat->material_category_id;
$optionKeys = Material::query()->where("material_category_id",$catId)->pluck("id")->map(fn($v)=>(int)$v)->all();
$selected = [ (int)$optionKeys[0] ];
$p->materials()->detach($optionKeys);
$p->materials()->attach($selected);
$after = $p->fresh()->materials()->pluck("materials.id")->all();
echo "categoria $catId optionKeys=".json_encode($optionKeys)." selected=".json_encode($selected)."\n";
echo "materiali dopo: ".json_encode($after)."\n";
// ripristino
$p->materials()->detach($optionKeys);
if($before) $p->materials()->syncWithoutDetaching($before);
echo "ripristinato: ".json_encode($p->fresh()->materials()->pluck("materials.id")->all())."\n";
