5	namespace App\Filament\Forms\Components;
6	
7	use App\Models\Product;
8	use Filament\Forms\Components\Field;
9	use Illuminate\Database\Eloquent\Model;
10	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
11	
12	/**
13	 * Selettore a checkbox annidati: le categorie sono righe collassabili
14	 * (accordion) con un checkbox padre a tre stati; espandendo la categoria si
15	 * apre l'elenco dei suoi item come dropdown di checkbox.
16	 *
17	 * Selezionando la categoria si attivano tutti gli item; deselezionando un item
18	 * la categoria non risulta più tutta selezionata (stato indeterminate). La
19	 * relazione è salvata sempre a livello di singolo item.
20	 */
21	class NestedCheckboxSelect extends Field
22	{
23	    protected string $view = 'filament.forms.components.nested-checkbox-select';
24	
25	    /** @var class-string<Model> */
26	    protected string $itemModel;
27	
28	    /** @var class-string<Model> */
29	    protected string $categoryModel;
30	
31	    protected string $categoryForeignKey;
32	
33	    protected string $noCategoryLabel = '';
34	
35	    /**
36	     * Configura la sorgente e il salvataggio della relazione BelongsToMany.
37	     *
38	     * @param string $name nome della relazione BelongsToMany su Product
39	     * @param class-string<Model> $itemModel modello degli item (Material/Fabric)
40	     * @param class-string<Model> $categoryModel modello della categoria
41	     * @param string $categoryForeignKey FK sull'item verso la categoria
