46	     * appendendole alla config di spatie, così il template non deve sapere
47	     * nulla del feature (config/settings.php resta infrastruttura pulita).
48	     *
49	     * @see \AtrioTeam\DigitalHub\Settings\GeneralSettings
50	     */
51	    private function registerSettings(): void
52	    {
53	        config([
54	            'settings.settings' => array_merge(
55	                (array) config('settings.settings', []),
56	                [\AtrioTeam\DigitalHub\Settings\GeneralSettings::class],
57	            ),
58	            'settings.migrations_paths' => array_merge(
59	                (array) config('settings.migrations_paths', []),
60	                [__DIR__ . '/../database/settings'],
61	            ),
62	        ]);
63	    }
64	
65	    /**
66	     * Auto-traduzione DeepL usata da {@see
67	     * \AtrioTeam\DigitalHub\Pim\Filament\Schemas\TranslationSection} quando
68	     * `autoTranslation()` è abilitata (roadmap #22c, internalizzata da
69	     * `atrioteam/filament-helper`). Il client DeepL è costruito con la chiave da
70	     * `config('digital-hub.deepl.api_key')`.
71	     */
72	    private function registerTranslation(): void
73	    {
74	        $this->app->bind(DeepLClient::class, function (): DeepLClient {
75	            $apiKey = config('digital-hub.deepl.api_key');
76	
77	            return new DeepLClient(is_string($apiKey) ? $apiKey : '');
78	        });
79	
80	        $this->app->bind(TranslateString::class, fn (Application $app): TranslateString => new TranslateString($app->make(DeepLClient::class)));
81	    }
82	
83	    /**
84	     * Pipeline di estrazione metadati ({@see MetadataExtractionPipeline}, design
85	     * §4.8). Gli estrattori sono risolti dal container nell'ordine dichiarato in
86	     * `config('digital-hub.metadata_extractors')` (ordine = priorità). Il template
87	     * estende/riordina la lista nella config; ogni voce dev'essere un
88	     * {@see MetadataExtractor}.
89	     */
90	    private function registerMetadataExtractionPipeline(): void
91	    {
92	        $this->app->singleton(MetadataExtractionPipeline::class, function (Application $app): MetadataExtractionPipeline {
93	            $extractors = [];
94	            foreach ((array) config('digital-hub.metadata_extractors', []) as $class) {
95	                if (! is_string($class)) {
96	                    continue;
97	                }
98	                $extractor = $app->make($class);
99	                if ($extractor instanceof MetadataExtractor) {
100	                    $extractors[] = $extractor;
101	                }
102	            }
103	
104	            return new MetadataExtractionPipeline($extractors);
105	        });
106	    }
107	
108	    public function boot(): void
109	    {
110	        $this->registerMorphAliases();
111	        $this->registerAssetsLogChannel();
112	
113	        $this->loadViewsFrom(__DIR__ . '/../resources/views', 'digital-hub');
114	        $this->loadTranslationsFrom(__DIR__ . '/../resources/lang', 'digital-hub');
115	        // Migrazioni owned dal package (es. asset_folders, colonna asset_folder_id
116	        // su media). Le migrazioni che aggiungono colonne a tabelle del cliente
117	        // restano nel template; queste sono tabelle del core, identiche per ogni
118	        // template, quindi viaggiano col package.
119	        $this->loadMigrationsFrom(__DIR__ . '/../database/migrations');
120	        // Route del package (serving gated degli asset su disco privato, 22d).
121	        $this->loadRoutesFrom(__DIR__ . '/../routes/web.php');
122	
123	        if ($this->app->runningInConsole()) {
124	            $this->commands([
125	                ReprocessAssetsCommand::class,
126	                ExtractMetadataCommand::class,
127	                MoveAssetsToPrivateDiskCommand::class,
128	            ]);
129	        }
130	
131	        $this->registerScheduledTasks();
132	    }
133	
134	    /**
135	     * Alias morph stabili per i modelli del core. Il template forza la morph map
136	     * (Relation::enforceMorphMap) e mappa i propri modelli di dominio, ma non
137	     * conosce quelli del package: il core registra qui i suoi. `morphMap` fa
138	     * merge (non sovrascrive), quindi convive con l'enforce del template a
139	     * prescindere dall'ordine di boot. Serve p.es. alla colonna polimorfica
140	     * `metadata.metadatable_type` (trait HasMetadata su TagGroup/TagCategory).
141	     */
142	    private function registerMorphAliases(): void
143	    {
144	        Relation::morphMap([
145	            'tag_group' => TagGroup::class,
146	            'tag_category' => TagCategory::class,
147	            'tag' => Tag::class,
148	        ]);
149	    }
150	
151	    /**
152	     * Pruning degli {@see \AtrioTeam\DigitalHub\Assets\Models\AssetShare}
153	     * scaduti — soprattutto gli share effimeri creati dal download multiplo
154	     * (22e). Usa `model:prune` (Prunable) schedulato, così il template non deve
155	     * configurare nulla. Lo scheduler dev'essere attivo (cron `schedule:run`).
156	     */
157	    private function registerScheduledTasks(): void
158	    {
159	        $this->callAfterResolving(Schedule::class, function (Schedule $schedule): void {
160	            $schedule->command('model:prune', [
161	                '--model' => [AssetShare::class],
162	            ])->hourly();
163	        });
164	    }
165	
166	    /**
167	     * Registra il channel di log dedicato `assets`, su cui scrive la pipeline di
168	     * elaborazione ({@see \AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob}):
169	     * fallimenti best-effort di poster/thumbnail (ffmpeg/Ghostscript) ed errori
170	     * del job. File dedicato così non si perdono nel rumore del log applicativo.
171	     *
172	     * Definito qui (non nel config/logging.php del template) per essere
173	     * self-contained col package; il template può comunque sovrascriverlo
174	     * dichiarando `logging.channels.assets`, nel qual caso questo è un no-op.
175	     */
176	    private function registerAssetsLogChannel(): void
177	    {
178	        if (config('logging.channels.assets') !== null) {
179	            return;
180	        }
181	
182	        config([
183	            'logging.channels.assets' => [
184	                'driver' => 'single',
185	                'path' => storage_path('logs/assets.log'),
186	                // riusa il LOG_LEVEL già risolto in config/logging.php (qui env()
187	                // sarebbe null con config cachata); fallback a debug.
188	                'level' => config('logging.channels.single.level', 'debug'),
189	                'replace_placeholders' => true,
190	            ],
191	        ]);
192	    }
193	}
